WITH u AS (SELECT u.id, u.email, u.name, coalesce(p.tz, (SELECT i.tz FROM ys_plan_items i WHERE i.owner_id = u.id ORDER BY i.updated_at DESC LIMIT 1), 'America/Chicago') AS tz FROM ys_users u LEFT JOIN ys_plan_prefs p ON p.owner_id = u.id WHERE u.active AND coalesce(p.digest, true) AND (u.email_verified OR u.google_sub IS NOT NULL) AND u.parent_email IS NULL AND coalesce(u.consent_status, '') NOT IN ('pending', 'approved', 'declined') AND u.email NOT LIKE '%.invalid' AND EXISTS (SELECT 1 FROM ys_plan_items i WHERE i.owner_id = u.id)), due AS (SELECT * FROM u WHERE extract(hour FROM now() AT TIME ZONE u.tz) = 7 AND NOT EXISTS (SELECT 1 FROM ys_plan_prefs p WHERE p.owner_id = u.id AND p.last_digest = (now() AT TIME ZONE u.tz)::date)) SELECT d.id, d.email, d.name, d.tz, to_char((now() AT TIME ZONE d.tz)::date, 'YYYY-MM-DD') AS day, to_char(now() AT TIME ZONE d.tz, 'FMDay, FMMonth FMDD') AS day_label, (SELECT json_agg(json_build_object('title', o.title, 'kind', o.kind, 'time', CASE WHEN o.all_day THEN 'All day' ELSE ltrim(to_char(o.occurs_at AT TIME ZONE d.tz, 'HH12:MI AM'), '0') END, 'notes', o.notes) ORDER BY o.all_day DESC, o.occurs_at) FROM ys_plan_occ(((now() AT TIME ZONE d.tz)::date)::timestamp AT TIME ZONE d.tz, (((now() AT TIME ZONE d.tz)::date + 1)::timestamp) AT TIME ZONE d.tz) o WHERE o.owner_id = d.id) AS items FROM due d
